sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    var photo = api.data.dt_req.result.traveller._reference.photo;
    return [{
        "label": "Photo",
        "value": {
            "type": "string",
            "value": photo
        }
    }];
}
